package com.chotomua.backend.modules.marketing;
import com.chotomua.backend.modules.marketing.dto.*; import com.chotomua.backend.modules.order.*; import com.chotomua.backend.modules.identity.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/reviews") public class ReviewController { private final ReviewRepository reviews; private final OrderItemRepository items; private final OrderRepository orders; private final EmployeeRepository employees; public ReviewController(ReviewRepository r,OrderItemRepository i,OrderRepository o,EmployeeRepository e){reviews=r;items=i;orders=o;employees=e;}
 /** Public homepage review showcase — highest-rated recent reviews with a comment. */
 @GetMapping public List<ReviewShowcaseResponse> showcase(@RequestParam(defaultValue = "6") int limit){ return reviews.findShowcase(Math.min(limit, 20)).stream().map(ReviewShowcaseResponse::from).toList(); }
 /** Staff moderation list (sales/cs/admin — see SecurityConfig); {@code unreplied=true} keeps only reviews still waiting for a reply. */
 @GetMapping("/manage") public List<ReviewManageResponse> manage(@RequestParam(defaultValue = "false") boolean unreplied){ return reviews.findForStaff(unreplied).stream().map(ReviewManageResponse::from).toList(); }
 @PostMapping public ResponseEntity<ReviewResponse> create(Authentication a,@Valid @RequestBody ReviewRequest q){UUID u=UUID.fromString((String)a.getPrincipal()); OrderItem item=items.findById(q.orderItemId()).orElseThrow(); Order order=orders.findByIdAndUserId(item.getOrderId(),u).orElseThrow(); if(!"delivered".equals(order.getStatus()))throw new IllegalStateException("Chỉ đánh giá đơn đã giao"); if(reviews.findByOrderItemId(item.getId()).isPresent())throw new IllegalStateException("Bạn đã đánh giá sản phẩm này"); return ResponseEntity.status(HttpStatus.CREATED).body(ReviewResponse.from(reviews.save(new Review(u,item.getId(),q.rating(),q.comment())))); }
 @PatchMapping("/{id}/reply") public ReviewResponse reply(Authentication a,@PathVariable UUID id,@Valid @RequestBody ReviewReplyRequest q){ Employee e=employees.findByUserId(UUID.fromString((String)a.getPrincipal())).orElseThrow(()->new AccessDeniedException("Không tìm thấy nhân viên")); if(!"sales".equals(e.getDepartment())&&!"cs".equals(e.getDepartment())&&!"admin".equals(e.getDepartment()))throw new AccessDeniedException("Không có quyền phản hồi đánh giá"); Review r=reviews.findById(id).orElseThrow(); r.reply(e.getId(),q.replyText().trim()); return ReviewResponse.from(reviews.save(r)); }
}
